<template><main><header><el-button @click="s.saveWorkflow">Save</el-button><el-button @click="s.validateWorkflow">Validate</el-button><el-button @click="run">Run</el-button><el-button @click="s.publishWorkflow">Publish</el-button><el-button @click="s.undo">Undo</el-button><el-button @click="s.redo">Redo</el-button></header><div class="work"><NodePalette @add="add"/><WorkflowCanvas/><PropertiesPanel/></div><DebugPanel/></main></template><script setup lang="ts">import{onMounted,onUnmounted}from'vue';import{useWorkflowStore}from'../stores/workflow';import{useRuntimeStore}from'../stores/runtime';import NodePalette from '../components/canvas/NodePalette.vue';import WorkflowCanvas from '../components/canvas/WorkflowCanvas.vue';import PropertiesPanel from '../components/panels/PropertiesPanel.vue';import DebugPanel from '../components/panels/DebugPanel.vue';const s=useWorkflowStore(),r=useRuntimeStore();const add=(type:any)=>s.addNode(type);const run=async()=>{const x=await s.runWorkflow('');r.connect(x.data.run_id)};const key=(e:KeyboardEvent)=>{if(e.ctrlKey&&e.key==='z')s.undo();if(e.ctrlKey&&e.key==='y')s.redo()};onMounted(()=>addEventListener('keydown',key));onUnmounted(()=>removeEventListener('keydown',key))</script><style scoped>main{height:100%;display:flex;flex-direction:column}header{padding:8px;border-bottom:1px solid #ddd}.work{display:flex;flex:1;min-height:0}.work>:nth-child(2){flex:1}</style>
